window.NGN_EXTRA['15'] = [
  { f: 'matrix', t: 'Peripheral vein or central line?', cj: 'ac', cn: 'pharm', st: ['pharm', 'safety'],
    q: 'For each infusion, indicate whether a short peripheral catheter is suitable or a central line is needed.',
    cols: ['Short peripheral catheter is suitable', 'Needs a central line'],
    rows: [{ t: '0.9% sodium chloride at 100 mL/hr for 2 days', a: 0, r: 'Isotonic, near-neutral and short term — a peripheral vein tolerates it.' },
      { t: 'Total parenteral nutrition, 1600 mOsm/L', a: 1, r: 'TPN runs over 1400 mOsm/L and is never given peripherally; it injures blood cells and the vein lining.' },
      { t: 'A continuous dopamine infusion', a: 1, r: 'Dopamine is a vesicant; a leak destroys tissue, so it belongs in a central vein.' },
      { t: 'An antibiotic with a pH of 4.2', a: 1, r: 'A pH under 5.0 damages small veins; the fast flow of a central vein dilutes it.' },
      { t: 'Lactated Ringer’s, 1 L over 8 hours', a: 0, r: 'Isotonic (273 mOsm/L) with an acceptable pH.' },
      { t: 'An infusate of 750 mOsm/L', a: 1, r: 'Over 600 mOsm/L is best given centrally.' }],
    ask: 'Is the pH between 5 and 9, the osmolarity under 600, and the drug not a vesicant?',
    cues: ['pH < 5 or > 9 → central', '> 600 mOsm/L → central', 'Vesicants, TPN → central'],
    phys: 'A small peripheral vein carries about 200 mL of blood a minute, so a harsh infusate stays concentrated against its lining → endothelial injury → phlebitis and thrombosis. The superior vena cava carries about 2 L a minute and dilutes it almost at once.',
    rule: 'Peripheral infusates: pH 5–9, osmolarity under about 500–600 mOsm/L, no vesicants, no TPN. Anything else needs a central tip at the cavoatrial junction.' },

  { f: 'matrix', t: 'Irritant or vesicant?', cj: 'ac', cn: 'pharm', st: ['pharm', 'alike'],
    q: 'For each drug, indicate whether your book lists it as an irritant (a phlebitis risk) or a vesicant (a tissue-destruction risk).',
    cols: ['Irritant', 'Vesicant'],
    rows: [{ t: 'Amiodarone', a: 0, r: 'A low-pH irritant; long peripheral courses inflame the vein.' },
      { t: 'Vancomycin', a: 0, r: 'An irritant — a classic cause of phlebitis over a long peripheral course.' },
      { t: 'Dopamine', a: 1, r: 'A vasoconstrictor vesicant: if it leaks, the tissue loses its blood supply.' },
      { t: 'Many chemotherapy drugs', a: 1, r: 'Many are vesicants: blistering, sloughing and necrosis if they leak.' },
      { t: 'Ciprofloxacin', a: 0, r: 'An irritant with a low pH.' }],
    ask: 'Does the drug inflame the vein, or destroy tissue if it escapes?',
    cues: ['Irritant → phlebitis', 'Vesicant → necrosis'],
    phys: 'Irritants injure the vein lining from inside (inflammation, phlebitis); vesicants injure the tissue outside the vein when they leak — vasoconstrictors by cutting off blood flow, chemotherapy by killing cells.',
    rule: 'Check every drug’s pH, osmolarity and vesicant potential before choosing the access. Irritants: amiodarone, vancomycin, ciprofloxacin. Vesicants: dopamine and many chemotherapy drugs.' },

  { f: 'matrix', t: 'Choosing the device', cj: 'gs', cn: 'pharm', st: ['subject'],
    q: 'For each client, indicate the most appropriate vascular access device.',
    cols: ['Short peripheral catheter', 'Midline catheter', 'PICC', 'Implanted port'],
    rows: [{ t: 'Two days of an isotonic IV antibiotic', a: 0, r: 'Short, peripheral-compatible therapy.' },
      { t: 'Ten days of a peripheral-compatible antibiotic in a client whose short catheters keep failing', a: 1, r: 'Midlines suit 6–14 days of peripheral-compatible therapy when veins make short catheters hard to keep.' },
      { t: 'Six weeks of IV antibiotics at home', a: 2, r: 'More than 14 days of therapy → a PICC.' },
      { t: 'Chemotherapy every 3 weeks for the next 18 months', a: 3, r: 'Therapy for more than a year → an implanted port (nothing outside; the least effect on body image).' },
      { t: 'Three weeks of total parenteral nutrition', a: 2, r: 'TPN needs a central tip; a PICC takes any infusate.' },
      { t: 'Rapid fluid resuscitation after a car crash', a: 0, r: 'A large-bore (14–16 gauge) short peripheral catheter delivers fluid fastest in trauma.' }],
    ask: 'How long will therapy last, and can a peripheral vein take the infusate?',
    cues: ['Days → short catheter', '6–14 days, peripheral-safe → midline', '> 14 days or any infusate → PICC', '> 1 year → port'],
    phys: 'The device is chosen to match the duration and the infusate: the longer the therapy and the harsher the drug, the more central and protected the catheter must be.',
    rule: 'Short peripheral: most short therapy (14–16 g for trauma). Midline: 6–14 days of peripheral-compatible therapy. PICC: > 14 days or any infusate. Tunneled catheter: weeks to months. Port: > 1 year.' },

  { f: 'mmatrix', t: 'Midline or PICC?', cj: 'ac', cn: 'pharm', st: ['alike'],
    q: 'For each statement, select the device or devices it describes. Each row may have more than one answer.',
    cols: ['Midline catheter', 'PICC'],
    rows: [{ t: 'The tip sits no farther than the axillary vein', a: [0], r: 'A midline is 3–8 inches long and stays peripheral.' },
      { t: 'The tip sits at the cavoatrial junction', a: [1], r: 'A PICC is a central line; its tip is confirmed before use.' },
      { t: 'Inserted in an upper-arm vein, the basilic preferred', a: [0, 1], r: 'Both use the larger, straighter basilic vein.' },
      { t: 'Can be used for parenteral nutrition', a: [1], r: 'No parenteral nutrition of any strength goes through a midline.' },
      { t: 'Suits 6 to 14 days of therapy', a: [0], r: 'Longer than 14 days → PICC.' },
      { t: 'No blood pressure cuff on that arm', a: [0, 1], r: 'Pressure irritates the vein and can damage either catheter.' },
      { t: 'Tip location must be confirmed by x-ray or ECG before any infusion', a: [1], r: 'Every central device has its tip confirmed before use.' }],
    ask: 'Is the tip peripheral or central — and which rules follow from that?',
    cues: ['Midline = peripheral rules', 'PICC = central rules', 'Both: arm devices'],
    phys: 'A midline is long but ends in the arm’s peripheral veins, where flow is slow; a PICC ends in the superior vena cava, where about 2 L/min of blood dilutes any infusate.',
    rule: 'Midline: pH 5–9, < 600 mOsm/L, no vesicants, no PN, no routine blood draws. PICC: any infusate, tip confirmed first, 10-mL syringes, baseline arm circumference.' },

  { f: 'selectn', t: 'Where not to place it', cj: 'ta', cn: 'safe', st: ['safety', 'neg'],
    q: 'The nurse is choosing a site for a short peripheral catheter. Select the 4 sites the nurse should avoid.',
    o: ['The palm side of the wrist', 'The antecubital fossa', 'The left forearm, on the side of a left mastectomy with lymph node dissection', 'The right forearm, which has a dialysis fistula', 'A straight vein in the nondominant forearm', 'A vein in the nondominant upper arm'], a: [0, 1, 2, 3],
    r: ['Avoid. The median nerve lies there, and the wrist is a joint of flexion.', 'Avoid. Joints of flexion kink the catheter and cause infiltration and phlebitis.', 'Avoid. An arm with a mastectomy and node dissection needs a provider’s order.', 'Avoid. Never use an arm with a fistula or graft.', 'Suitable. The forearm of the nondominant arm, starting distally.', 'Suitable. Upper-arm veins are acceptable peripheral sites.'],
    ask: 'Which sites risk a nerve, a flexing joint, or an arm that must be protected?',
    cues: ['Wrist, flexion joints', 'Mastectomy, node dissection', 'Fistula'],
    phys: 'Flexion bends the catheter against the vein wall; impaired lymph drainage after node dissection raises the risk of infection and lymphedema; a fistula carries high-pressure arterial flow that must be preserved for dialysis.',
    rule: 'Box 15.1: upper extremity, nondominant arm, distal first; never the wrist, joints of flexion, hard or cordlike veins, or an arm with a mastectomy, lymph node dissection, fistula or graft, or paralysis.' },

  { f: 'hl', t: 'Checking the IV site', cj: 'rc', cn: 'pharm', st: ['abnormal'],
    q: 'A client has 0.9% sodium chloride infusing through a short peripheral catheter in the right forearm. Read the nurse’s note. Highlight the findings that need follow-up.',
    parts: ['1400 — ', { h: 'Area around the insertion site swollen, about 3 cm across', c: 1, r: 'Follow up. Edema at the site — fluid is leaking into the tissue (infiltration).' }, '. ',
      { h: 'Skin over the site cool and tight', c: 1, r: 'Follow up. The leaking fluid is cooler than the body and stretches the skin.' }, '. ',
      { h: 'Client says the area “burns a little”', c: 1, r: 'Follow up. Burning or discomfort is an early sign of infiltration.' }, '. ',
      { h: 'Infusion rate has slowed from 100 to 60 mL/hr on gravity', c: 1, r: 'Follow up. A slowing rate goes with a catheter that has slipped out of the vein.' }, '. ',
      { h: 'Dressing transparent and intact', c: 0, r: 'Expected — though the site beneath it needs attention.' }, '. ',
      { h: 'Label shows the right client and the right fluid', c: 0, r: 'Correct; not a problem.' }, '. ',
      { h: 'Radial pulse strong', c: 0, r: 'Normal circulation to the hand.' }, '.'],
    ask: 'Which findings show fluid leaking into the tissue?',
    cues: ['Swelling', 'Cool, tight skin', 'Burning', 'Slowing rate'],
    phys: 'When the catheter tip leaves the vein, the infusate collects in the tissue: it swells the area, cools and tightens the skin, presses on nerve endings and meets more resistance, so the rate slows.',
    rule: 'Infiltration: stop the infusion, remove the catheter, elevate the arm, warm or cool compresses per policy, restart in the opposite arm. Check sites at least every 4 hours with a continuous infusion.' },

  { f: 'bow', t: 'Breathless during a bolus', cj: 'ta', cn: 'pharm', st: ['abc', 'data'],
    q: 'An 82-year-old client with heart failure is receiving 0.9% sodium chloride at 150 mL/hr. Three hours into the infusion the client is short of breath and coughing, with crackles in both bases, distended neck veins, puffy eyelids and BP 168/94 (baseline 132/78). Complete the diagram: the condition the client is most likely experiencing, 2 actions to take and 2 parameters to monitor.',
    cond: { o: ['Circulatory overload', 'Speed shock', 'Catheter-related bloodstream infection', 'Air embolism'], a: 0,
      r: ['Correct. Dyspnea, cough, crackles, distended neck veins, edema and a rising BP during an isotonic infusion in an older adult with heart failure.', 'Incorrect. Speed shock follows a drug given too fast — dizziness, chest tightness, a flushed face and an irregular pulse.', 'Incorrect. CRBSI brings fever, chills and malaise.', 'Incorrect. Air embolism is sudden, with chest pain and hypotension — not gradual fluid signs.'] },
    act: { o: ['Slow the infusion and notify the provider', 'Raise the head of the bed to sit the client upright', 'Increase the rate to finish the infusion sooner', 'Place the client flat with the legs raised', 'Remove the IV catheter at once'], a: [0, 1],
      r: ['Correct. Less fluid in, and the provider may order a diuretic.', 'Correct. Sitting up eases breathing and pools fluid away from the lungs.', 'Incorrect. More fluid worsens the overload.', 'Incorrect. Lying flat with the legs up sends more fluid to the lungs.', 'Incorrect. Access may be needed for a diuretic; slow the rate instead.'] },
    mon: { o: ['Breath sounds, respiratory rate and SpO₂', 'Intake and output, with daily weights', 'Capillary blood glucose', 'Temperature every 4 hours', 'Pupil size and reaction'], a: [0, 1],
      r: ['Correct. Crackles clearing and SpO₂ rising show the lungs are drying.', 'Correct. Output exceeding intake and a falling weight show the excess leaving.', 'Incorrect. Not related to the volume problem.', 'Incorrect. Fever isn’t a sign of overload.', 'Incorrect. Not related.'] },
    ask: 'Is the body receiving more fluid than the heart can move?',
    cues: ['82, heart failure', 'Isotonic at 150 mL/hr', 'Crackles, distended neck veins, ↑BP'],
    phys: 'Isotonic fluid stays in the extracellular space → plasma volume rises faster than a weak heart and aging kidneys can handle → venous pressure rises (distended neck veins) → fluid moves into the alveoli (crackles, dyspnea) and tissues (edema).',
    rule: 'Circulatory overload (Table 15.4): slow the infusion and notify, sit upright, monitor vital signs and breathing, oxygen and diuretics as prescribed. Prevent with careful intake and output, and pumps for accuracy in older adults.' },

  { f: 'bow', t: 'Fever with a PICC', cj: 'ta', cn: 'safe', st: ['data', 'safety'],
    q: 'A client has had a PICC for 3 weeks for home antibiotics and comes to the clinic feeling unwell. T 102.2°F (39°C), shaking chills, headache, HR 112, BP 98/60. The insertion site looks clean. Complete the diagram: the condition the client is most likely experiencing, 2 actions to take and 2 parameters to monitor.',
    cond: { o: ['Catheter-related bloodstream infection', 'Phlebitis', 'Circulatory overload', 'Catheter migration'], a: 0,
      r: ['Correct. Fever, chills, headache and malaise, now with tachycardia and a falling BP, in a client with a central line — even with a clean site.', 'Incorrect. Phlebitis is local: pain, redness and a hard vein.', 'Incorrect. Overload brings dyspnea, crackles and a high BP.', 'Incorrect. Migration causes a gurgling sound, back pain or neurologic signs, not fever.'] },
    act: { o: ['Obtain blood cultures as prescribed before antibiotics are given', 'Change the whole infusion system and send the infusate for culture if asked', 'Flush the PICC forcefully to clear any clot', 'Apply warm compresses to the upper arm', 'Tell the client to rest and recheck the temperature tomorrow'], a: [0, 1],
      r: ['Correct. Cultures identify the organism; antibiotics follow as prescribed.', 'Correct. The tubing, fluid or catheter may be the source.', 'Incorrect. Forceful flushing can rupture the catheter or push a clot loose.', 'Incorrect. That treats phlebitis, not a bloodstream infection.', 'Incorrect. Falling BP and a rising HR mean this could become sepsis.'] },
    mon: { o: ['Temperature, heart rate and blood pressure', 'Urine output', 'Arm circumference compared with the baseline', 'Bowel sounds', 'Blood glucose'], a: [0, 1],
      r: ['Correct. Tachycardia and hypotension signal sepsis.', 'Correct. Low urine output is a late sign of poor perfusion.', 'Incorrect. That tracks thrombosis.', 'Incorrect. Not related.', 'Incorrect. Not the priority here.'] },
    ask: 'Could the line itself be seeding the blood?',
    cues: ['PICC 3 weeks', 'Fever 102.2°F, chills', 'HR 112, BP 98/60'],
    phys: 'Organisms reach the catheter from the skin (along the outside) or from handled hubs (through the inside) → they grow on the catheter surface → seed the bloodstream → fever and chills → tachycardia, hypotension and low urine as sepsis develops.',
    rule: 'CRBSI (Table 15.5): early fever, chills, headache, malaise; later tachycardia, hypotension, low urine output. Change the whole system, notify, cultures, antibiotics as prescribed. Prevent with sterile technique, scrubbing the hub and the CRBSI bundle.' },

  { f: 'ddr', t: 'A shorter catheter', cj: 'ph', cn: 'rrp', st: ['abnormal', 'safety'],
    q: 'The nurse removes a PICC from a client’s right arm. The catheter measures 4 cm shorter than the length documented at insertion, and the tip looks ragged. Complete the sentence.',
    parts: ['The client is most at risk for ', { o: ['catheter embolism', 'air embolism', 'phlebitis'], a: 0, r: 'A broken piece of catheter can travel to the heart or lungs and cause cardiopulmonary arrest.' },
      ', so the nurse first ', { o: ['applies a tourniquet high on the upper arm and notifies the provider emergently', 'applies an occlusive dressing and documents the length', 'applies warm compresses and reassesses in an hour'], a: 0, r: 'The tourniquet slows the fragment’s travel; it is an emergency needing imaging and possible retrieval.' },
      ', as shown by ', { o: ['the missing length and ragged tip', 'bleeding at the site', 'redness along the vein'], a: 0, r: 'Comparing the removed catheter with the insertion length is how embolism is found.' }, '.'],
    ask: 'Where is the missing piece, and what keeps it from moving?',
    cues: ['4 cm shorter', 'Ragged tip'],
    phys: 'A catheter fragment inside a vein is carried by the blood toward the right heart and pulmonary arteries → it can lodge there, cause dysrhythmias or block flow → cardiopulmonary arrest.',
    rule: 'Catheter embolism: notify emergently, tourniquet high on the limb, keep what was removed, x-ray. Prevent: never reinsert the needle into an over-the-needle catheter, never pull a catheter back through a needle, no scissors near the line; always measure a removed catheter.' },

  { f: 'order', t: 'Removing a central venous catheter', cj: 'ta', cn: 'rrp', st: ['np', 'safety'],
    q: 'Place the steps for removing a nontunneled central venous catheter in order.',
    o: ['Explain the procedure and position the client flat or in Trendelenburg', 'Remove the dressing, peeling toward the insertion site, with the line clamped', 'Have the client hold the breath or bear down while the catheter is withdrawn', 'Press gauze on the site until bleeding stops', 'Apply an occlusive dressing to stay on for at least 24 hours', 'Measure the catheter and compare it with the insertion length, then document'], a: [0, 1, 2, 3, 4, 5],
    r: ['First: lying flat keeps the pressure in the chest above air pressure.', 'Second: peeling toward the site avoids pulling the catheter out early.', 'Third: Valsalva raises intrathoracic pressure so air can’t be drawn in.', 'Fourth: hemostasis.', 'Fifth: the occlusive dressing seals the tract against air.', 'Last: a shorter catheter means a fragment may have broken off — an emergency.'],
    ask: 'At which moment can air enter, and what keeps it out?',
    cues: ['Flat', 'Clamped', 'Valsalva', 'Occlusive dressing 24 hr', 'Measure'],
    phys: 'Breathing in lowers the pressure in the chest; with an open tract from skin to vein, that can pull air into the circulation. Lying flat, bearing down and sealing the tract keep it out.',
    rule: 'Central line removal: flat or Trendelenburg, clamped, Valsalva (on a ventilator, during an inhalation breath), pressure until hemostasis, occlusive dressing ≥ 24 hours, measure the catheter, report a short one at once.' },

  { f: 'cloze', t: 'Flushing a central line', cj: 'ta', cn: 'pharm', st: ['safety'],
    q: 'Complete the teaching about flushing a central venous catheter.',
    parts: ['Central lines are flushed with a ', { o: ['10-mL syringe', '3-mL syringe', '1-mL syringe'], a: 0, r: 'A larger barrel spreads the push over more area, so the pressure stays low.' },
      ' because a smaller syringe ', { o: ['creates more pressure and can rupture the catheter', 'holds too little saline', 'can’t be used with needleless connectors'], a: 0, r: 'Pressure = force ÷ area; a narrow barrel concentrates the same thumb force.' },
      '. Before flushing, the nurse aspirates to check for ', { o: ['a brisk blood return', 'air in the line', 'the drug level'], a: 0, r: 'A blood return shows the catheter is patent and in the vein.' },
      '. If the nurse meets resistance, the nurse ', { o: ['stops and does not force it', 'pushes harder', 'switches to a smaller syringe'], a: 0, r: 'Forcing can burst the catheter or push a clot into the circulation.' },
      ', and uses a ', { o: ['push-pause technique', 'single rapid push', 'gravity drip'], a: 0, r: 'Push-pause creates turbulence that clears the lumen.' }, '.'],
    ask: 'Why do syringe size and resistance matter?',
    cues: ['10-mL syringe', 'Blood return', 'Stop at resistance'],
    phys: 'Pressure is force spread over area: the narrower the syringe, the higher the pressure inside the catheter — enough to rupture it or dislodge a clot against a partial blockage.',
    rule: 'Flushing: saline (heparin only if the device calls for it), slow and gentle, check for a blood return, stop at any resistance, 10-mL syringes for central lines, push-pause, prefilled single-use syringes, flush right after each use.' },

  { f: 'group', t: 'Phlebitis or a clot?', cj: 'gs', cn: 'pharm', st: ['alike', 'subject'],
    q: 'For each client with a short peripheral catheter, select all the actions that apply.',
    groups: [{ h: 'The vein above the site is red, warm and painful, and feels like a hard cord', o: ['Remove the catheter', 'Apply a warm compress', 'Apply a cold compress', 'Leave the catheter in and slow the rate'], a: [0, 1],
        r: ['Correct. Remove a peripheral catheter at the first sign of phlebitis.', 'Correct. Warmth soothes the inflamed vein.', 'Incorrect. Cold is used for a thrombosis.', 'Incorrect. Leaving it in prolongs the injury.'] },
      { h: 'The forearm is swollen and tender and the infusion has slowed; no redness along the vein', o: ['Stop the infusion and remove the catheter', 'Apply a cold compress and elevate the arm', 'Apply a warm compress first', 'Push saline through the catheter forcefully'], a: [0, 1],
        r: ['Correct. A clot is suspected; stop and remove.', 'Correct. Cold narrows the vessels and slows the clot’s spread; elevation reduces swelling.', 'Incorrect. Warmth is for phlebitis (or after cold in thrombophlebitis).', 'Incorrect. Forcing a flush can push the clot into the circulation.'] }],
    ask: 'Is the vein inflamed, or is it blocked?',
    cues: ['Red, warm, cordlike → phlebitis', 'Swollen limb, slowed flow → thrombosis'],
    phys: 'Phlebitis is inflammation of the vein wall (redness, warmth, pain, a hard cord); thrombosis is a clot that blocks flow (a swollen limb and a slowing infusion). Warmth opens and soothes; cold narrows and slows.',
    rule: 'Phlebitis: remove the peripheral catheter, warm compresses, phlebitis scale, restart in the other arm. Thrombosis: stop, remove, cold compresses, elevate. Thrombophlebitis: cold first, then warm.' },

  { f: 'ddt', t: 'Complication and action', cj: 'ta', cn: 'pharm', st: ['alike', 'safety'],
    q: 'For each finding during an infusion, choose the complication and the nurse’s best action.',
    head: ['Finding', 'Complication', 'Best action'],
    rows: [['Dopamine infusing peripherally; the site is pale, cold and starting to blister', { o: ['Extravasation', 'Infiltration', 'Phlebitis'], a: 0, r: 'A vesicant leaking into tissue.' },
        { o: ['Stop and disconnect, aspirate the drug, leave the catheter in for the antidote, photograph the site', 'Remove the catheter at once and apply a warm compress', 'Slow the rate and recheck in an hour'], a: 0, r: 'Aspirate what you can and keep the access for the antidote.' }],
      ['Cramping pain above the site; the infusion of cold fluid has slowed', { o: ['Venous spasm', 'Thrombosis', 'Nerve injury'], a: 0, r: 'Cold or irritating fluid can make the vein spasm.' },
        { o: ['Slow the rate and apply a warm compress; don’t remove the catheter', 'Remove the catheter and apply ice', 'Apply a tourniquet above the site'], a: 0, r: 'Warmth relaxes the vein; room-temperature fluids prevent it.' }],
      ['Lightheaded, chest tight and flushed right after an IV push; pulse irregular', { o: ['Speed shock', 'Circulatory overload', 'Air embolism'], a: 0, r: 'A drug given too fast reaches toxic levels.' },
        { o: ['Stop the drug, run isotonic fluid to keep the vein open and notify the provider', 'Give the rest of the dose more slowly', 'Raise the legs and give a fluid bolus'], a: 0, r: 'Stop the drug; keep the access open; monitor and report.' }]],
    ask: 'What does each finding say about where the problem is?',
    cues: ['Vesicant + blisters → extravasation', 'Cramping, slowed → spasm', 'After a fast push → speed shock'],
    phys: 'A vesicant destroys tissue outside the vein; a spasm narrows the vein itself; a drug pushed too fast reaches the heart and brain at a toxic concentration.',
    rule: 'Tables 15.3 and 15.4: extravasation — stop, disconnect, aspirate, antidote, cold except vinca alkaloids and epipodophyllotoxins, photograph; spasm — warm, slow, don’t remove; speed shock — stop, isotonic KVO, notify; follow each drug’s rate.' },

  { f: 'sata', t: 'The central-line bundle', cj: 'gs', cn: 'safe', st: ['safety'],
    q: 'The nurse is assisting with insertion of a central venous catheter. Which actions are part of the CRBSI prevention bundle? Select all that apply.',
    o: ['Using a checklist, with authority to stop anyone who breaks technique', 'Maximal barrier precautions, with the client draped head to toe', 'Chlorhexidine skin preparation', 'Choosing a site other than the femoral vein when possible', 'Reviewing every day whether the line is still needed', 'Replacing the catheter routinely every 72 hours', 'Shaving the insertion site'], a: [0, 1, 2, 3, 4],
    r: ['Correct. The checklist makes everyone a safety monitor.', 'Correct. The inserter wears sterile gloves, gown and mask; everyone in the room is masked.', 'Correct. Chlorhexidine is the preferred antiseptic.', 'Correct. The femoral vein has the highest infection rate.', 'Correct. Removing the line as soon as it isn’t needed is the most powerful step.', 'Incorrect. Routine replacement isn’t part of the bundle; each new insertion adds risk.', 'Incorrect. Shaving makes microabrasions; clip if needed.'],
    ask: 'Which steps keep organisms out of the line and shorten its dwell?',
    cues: ['Checklist', 'Barriers', 'Chlorhexidine', 'Avoid femoral', 'Daily review'],
    phys: 'Organisms reach the blood along the outside of the catheter from the skin, or through the inside from handled hubs; every day of dwell adds risk.',
    rule: 'Box 15.3: checklist with authority to stop, hand hygiene, time-out, maximal barriers, minimal traffic, chlorhexidine, best site (avoid femoral), meticulous post-insertion care, daily review of need.' },

  { f: 'exhibit', t: 'No blood return from the port', cj: 'ta', cn: 'pharm', st: ['safety', 'data'],
    q: 'Review the note. What is the nurse’s best action?',
    ex: [{ h: 'Nurse’s note', lines: ['Client with an implanted chest port is due for a vesicant chemotherapy drug.', 'Port accessed with a noncoring needle using mask and aseptic technique.', 'Saline flushes easily, with no swelling or pain; no blood return on aspiration.'] }],
    o: ['Hold the chemotherapy until the port’s patency and the needle’s position are confirmed', 'Give the chemotherapy, since the saline flushes easily', 'Push the chemotherapy faster so it reaches the vein before it can leak', 'Remove the needle and give the drug through a small peripheral vein'], a: [0],
    r: ['Correct. Without a blood return, a fibrin sheath or a misplaced needle could send the vesicant into the tissue.', 'Incorrect. Easy flushing doesn’t prove the fluid is reaching the vein.', 'Incorrect. Speed doesn’t prevent extravasation and risks speed shock.', 'Incorrect. A vesicant shouldn’t go into a small vein.'],
    ask: 'What does a missing blood return mean before a vesicant?',
    cues: ['Vesicant due', 'Flushes easily', 'No blood return'],
    phys: 'A fibrin sheath can coat the catheter tip like a sleeve: saline goes in, but blood can’t be drawn back, and fluid may track backward along the sheath into the tissue.',
    rule: 'Before any drug through a port: aspirate for a blood return the color and consistency of whole blood. No blood return → hold the drug until patency and needle placement are confirmed.' },

  { f: 'matrix', t: 'When to change the tubing', cj: 'ta', cn: 'safe', st: ['safety'],
    q: 'For each administration set, indicate how often it is changed.',
    cols: ['Within 4 hours', 'Every 12 hours', 'Every 24 hours', 'Up to 7 days'],
    rows: [{ t: 'Blood transfusion tubing', a: 0, r: 'Blood tubing is changed within 4 hours.' },
      { t: 'Tubing for lipids given alone', a: 1, r: 'Lipids support bacterial growth — every 12 hours.' },
      { t: 'Tubing for parenteral nutrition', a: 2, r: 'PN tubing is changed every 24 hours.' },
      { t: 'An intermittent set disconnected after each dose', a: 2, r: 'Both ends are handled each dose — every 24 hours.' },
      { t: 'A continuous primary set', a: 3, r: 'Up to 7 days (it may be changed every 96 hours).' }],
    ask: 'How easily can organisms grow in what runs through the set?',
    cues: ['Blood 4 hr', 'Lipids 12 hr', 'PN and intermittent 24 hr', 'Continuous ≤ 7 days'],
    phys: 'Blood, lipids and nutrient solutions are rich growth media, and every disconnection is a chance for contamination — so the richer the fluid and the more the set is handled, the shorter its life.',
    rule: 'Continuous primary and secondary sets: up to 7 days (or every 96 hours). Intermittent sets: 24 hours. PN: 24 hours. Lipids alone: 12 hours. Blood tubing: within 4 hours.' },

  { f: 'dnd', t: 'How catheters become infected', cj: 'ac', cn: 'safe', st: ['subject'],
    q: 'Complete the explanation. Place a word or phrase in each blank.',
    parts: ['Organisms reach a catheter along its outside from the ', { a: 0, r: 'Skin organisms track along the catheter into the tract.' },
      ', which is why a site on the warm, moist ', { a: 2, r: 'Neck and chest skin carries far more organisms than the cool, dry upper arm.' },
      ' infects more often than a PICC. They also enter through the inside when ', { a: 4, r: 'Every access of a hub is a chance to carry organisms in — scrub the hub.' },
      ' are handled. A tunnel and a ', { a: 6, r: 'Tissue grows into the cuff, sealing the tract and anchoring the catheter.' }, ' block the outside route.'],
    tokens: ['skin', 'blood', 'neck and chest', 'upper arm', 'hubs', 'dressings', 'cuff', 'needle'],
    ask: 'Which two routes do organisms take into a catheter?',
    cues: ['Outside: skin', 'Inside: hubs', 'Tunnel and cuff'],
    phys: 'Skin organisms migrate along the outer surface of the catheter into the tract, while contaminated hubs let organisms into the lumen; both seed the bloodstream, and the risk rises with every day of dwell.',
    rule: 'Prevent CRBSI: chlorhexidine skin prep, scrub the hub before every access, sterile dressings, the bundle at insertion, and remove the line as soon as it isn’t needed.' },

  { f: 'sata', t: 'Starting an IV in an older adult', cj: 'ta', cn: 'pharm', st: ['safety', 'client'],
    q: 'The nurse is starting a short peripheral catheter in an 88-year-old client with thin skin and rolling veins. Which actions are appropriate? Select all that apply.',
    o: ['Apply a flat tourniquet over the gown sleeve', 'Insert the catheter at a low angle, 10 to 15 degrees', 'Choose a vein higher on the forearm instead of the back of the hand', 'Clip the hair instead of shaving', 'Apply a skin protectant before the dressing', 'Leave the tourniquet on until the dressing is in place', 'Use povidone-iodine and let it dry for 30 seconds'], a: [0, 1, 2, 3, 4],
    r: ['Correct. A flat tourniquet over cloth protects fragile skin.', 'Correct. A low angle with good skin traction suits superficial, rolling veins.', 'Correct. Hand veins in older adults are fragile and tortuous.', 'Correct. Shaving makes microabrasions that invite infection.', 'Correct. It protects the skin from tears when the adhesive is removed.', 'Incorrect. Release it as soon as the catheter enters to prevent a hematoma.', 'Incorrect. Povidone-iodine needs 2 minutes of contact; chlorhexidine is preferred.'],
    ask: 'How does aging change the skin and the veins?',
    cues: ['Thin skin', 'Rolling veins', 'Fragile hand veins'],
    phys: 'Aging skin is thinner, with less fat and fewer nerve endings — easier to tear and slower to warn of a bad stick; veins roll and fill slowly.',
    rule: 'Older adults: no hand veins, flat tourniquet over cloth (or a BP cuff below diastolic), warmth or arm down to fill veins, 10–15° angle, release the tourniquet early, clip don’t shave, chlorhexidine, skin protectant, adhesive remover.' },

  { f: 'matrix', t: 'Special routes, special dangers', cj: 'ph', cn: 'rrp', st: ['subject', 'safety'],
    q: 'For each access, indicate the complication the nurse watches for most closely.',
    cols: ['Hemorrhage from a disconnection', 'Meningitis or a neurologic change', 'Peritonitis', 'Compartment syndrome'],
    rows: [{ t: 'A radial arterial line for pressure monitoring', a: 0, r: 'Arterial pressure means a loose connection can bleed out fast — Luer-Lok every connection.' },
      { t: 'An epidural catheter for postoperative pain', a: 1, r: 'Watch for a stiff neck, temperature over 101 °F, an epidural hematoma and any neurologic change.' },
      { t: 'Intraperitoneal chemotherapy', a: 2, r: 'Fever, a rigid abdomen and rebound tenderness signal peritonitis.' },
      { t: 'An intraosseous needle in the proximal tibia', a: 3, r: 'Infiltration into the closed leg compartment can cut perfusion: coolness, swelling, mottling.' },
      { t: 'An intrathecal catheter for spasticity', a: 1, r: 'Drugs go straight into the CSF; infection and bleeding reach the nervous system.' }],
    ask: 'What is each space next to, and what can go wrong there?',
    cues: ['Artery: pressure', 'Spinal: cord and CSF', 'Peritoneum: closed space', 'Bone: closed compartment'],
    phys: 'Arteries carry high pressure (bleeding), the spinal spaces lie against the cord (infection, hematoma), the peritoneum is a large closed space (infection, pressure on the lungs), and an IO leak fills a closed muscle compartment.',
    rule: 'Arterial: Luer-Lok, distal pulse, warmth, refill. Intraspinal: filter, preservative-free drugs, no alcohol at the site, neuro checks. Intraperitoneal: semi-Fowler’s, asepsis, watch for peritonitis. Intraosseous: ≤ 24 hours, watch the limb.' },

  { f: 'hlt', trend: true, t: 'A leg with an IO needle', cj: 'rc', cn: 'rrp', st: ['trend', 'abnormal'],
    q: 'A client in cardiac arrest had an intraosseous needle placed in the left proximal tibia. Highlight the findings that need follow-up.',
    head: ['Finding', '0100', '0300', '0500'],
    rows: [{ cells: ['Left calf circumference', '36 cm', '38 cm', '41 cm'], c: 1, r: 'Follow up. A growing calf means fluid is collecting in the compartment.' },
      { cells: ['Left foot color', 'Pink', 'Pale', 'Mottled'], c: 1, r: 'Follow up. Mottling signals poor perfusion — possible compartment syndrome.' },
      { cells: ['Left foot temperature', 'Warm', 'Cool', 'Cold'], c: 1, r: 'Follow up. A cooling foot is losing its blood supply.' },
      { cells: ['Fluid seen under the skin at the site', 'No', 'Slight', 'Yes'], c: 1, r: 'Follow up. Infiltration — the most common IO complication.' },
      { cells: ['Right foot color', 'Pink', 'Pink', 'Pink'], c: 0, r: 'The other leg is normal — a useful comparison.' },
      { cells: ['Time since insertion', '3 hr', '5 hr', '7 hr'], c: 0, r: 'Within the 24-hour limit — not the problem by itself.' }],
    ask: 'Which trend shows a leg losing its circulation?',
    cues: ['Calf 36 → 41 cm', 'Pink → mottled', 'Warm → cold'],
    phys: 'Infusate leaking from a misplaced IO needle fills the closed muscle compartment → pressure rises above capillary pressure → blood flow to muscle and nerve falls → swelling, coolness, mottling → possible amputation.',
    rule: 'Intraosseous: short term only (≤ 24 hours); infiltration is the most common complication; watch for compartment syndrome — coolness, swelling, mottling, discoloration — and report at once.' },

  { f: 'calc', t: 'Setting the rate', cj: 'ta', cn: 'pharm', st: ['calc'],
    q: 'The prescription reads: 0.9% sodium chloride 1000 mL IV over 8 hours. At how many mL per hour should the nurse set the infusion pump? Record your answer as a whole number.',
    ans: 125, unit: 'mL/hr', dp: 0, work: '1000 mL ÷ 8 hr = 125 mL/hr.',
    ask: 'Can you turn a volume over time into an hourly rate?',
    cues: ['1000 mL', '8 hours'],
    phys: 'A pump delivers a set volume each hour; dividing the total volume by the hours spreads it evenly so the client receives the fluid at the prescribed pace.',
    rule: 'A complete fluid order gives the fluid, the rate in mL/hr (or a total volume over a set time) and any additives. mL/hr = total mL ÷ hours.' },

  { f: 'calc', t: 'Counting drops', cj: 'ta', cn: 'pharm', st: ['calc'],
    q: 'No pump is available. The nurse must infuse 500 mL of lactated Ringer’s over 4 hours with tubing that delivers 15 drops per mL. How many drops per minute should the nurse count? Round to the nearest whole number.',
    ans: 31, unit: 'gtt/min', dp: 0, work: '500 mL × 15 gtt/mL = 7500 gtt; 4 hr × 60 = 240 min; 7500 ÷ 240 = 31.25 → 31 gtt/min.',
    ask: 'Can you convert a volume and time into drops per minute?',
    cues: ['500 mL', '4 hours', '15 gtt/mL'],
    phys: 'The drop factor tells how many drops make 1 mL; multiplying by the volume gives the total drops, and dividing by the minutes gives the drip rate.',
    rule: 'gtt/min = (mL × drop factor) ÷ minutes. Recheck gravity rates often; an electronic pump is preferred for accuracy, especially in older adults.' },

  { f: 'ddr', t: 'TPN through a midline', cj: 'ph', cn: 'pharm', st: ['safety', 'pharm'],
    q: 'A client with a midline catheter in the left upper arm has a new prescription for parenteral nutrition through the midline. Complete the sentence.',
    parts: ['The nurse should ', { o: ['question the prescription and ask about central access', 'start the PN at a slower rate', 'dilute the PN with saline'], a: 0, r: 'A midline ends in a peripheral vein; PN of any strength doesn’t belong there.' },
      ' because the client is at risk for ', { o: ['phlebitis and thrombosis from a hypertonic solution in a small vein', 'circulatory overload', 'speed shock'], a: 0, r: 'PN runs over 1400 mOsm/L; in slow peripheral flow it injures the lining.' },
      ', and the device that should be used is ', { o: ['a PICC with its tip at the cavoatrial junction', 'a second midline in the other arm', 'a short peripheral catheter'], a: 0, r: 'PN needs a central tip, where about 2 L/min of blood dilutes it.' }, '.'],
    ask: 'Is a midline a central line?',
    cues: ['Midline', 'Parenteral nutrition'],
    phys: 'A midline is long but ends no farther than the axillary vein, where blood flow is slow; a hypertonic nutrient solution there stays concentrated against the vein wall.',
    rule: 'Midlines follow peripheral rules: pH 5–9, < 600 mOsm/L, no vesicants, no PN of any strength, no routine blood draws. Ask about anything unclear before giving it.' },

  { f: 'mmatrix', t: 'Cold, warm or neither?', cj: 'gs', cn: 'pharm', st: ['alike'],
    q: 'For each complication, select what your book recommends. Each row may have more than one answer.',
    cols: ['Cold compress', 'Warm compress', 'Remove a peripheral catheter'],
    rows: [{ t: 'Phlebitis at a short peripheral catheter', a: [1, 2], r: 'Remove at the first sign; warmth soothes the vein.' },
      { t: 'Thrombosis at a short peripheral catheter', a: [0, 2], r: 'Stop, remove, cold compresses and elevate.' },
      { t: 'Venous spasm', a: [1], r: 'Warmth relaxes the vein; slow the rate and don’t remove the catheter.' },
      { t: 'A hematoma in the first 24 hours', a: [0], r: 'Ice for 24 hours, then warmth.' },
      { t: 'Extravasation of a vinca alkaloid', a: [1], r: 'Vinca alkaloids and epipodophyllotoxins are the exceptions to cold; keep the catheter for the antidote.' }],
    ask: 'Does this problem need vessels narrowed or opened?',
    cues: ['Cold narrows', 'Warm opens', 'Vinca alkaloids are the exception'],
    phys: 'Cold narrows vessels — it slows a clot’s spread, limits bleeding and keeps most vesicants in place; warmth opens them — it eases spasm, soothes phlebitis and spreads the few vesicants that harm more when concentrated.',
    rule: 'Phlebitis: remove, warm. Thrombosis: remove, cold, elevate. Spasm: warm, slow, keep it. Hematoma: ice 24 hours, then warm. Extravasation: cold except vinca alkaloids and epipodophyllotoxins (warm).' }
];

